package com.gamehub.personnel;
import java.math.BigDecimal; import java.util.*;
public final class GameHubPayrollDemo { private GameHubPayrollDemo(){} public static List<Employee> sample(){List<Employee> x=new ArrayList<>();for(int i=1;i<=4;i++)x.add(new Faculty("F"+i,"Faculty "+i,"Campus","Lahore",new BigDecimal("450000"),"Professor",new BigDecimal("60000"),new BigDecimal("95000"),new BigDecimal("10000"),BigDecimal.ZERO));for(int i=1;i<=2;i++)x.add(new Staff("S"+i,"Staff "+i,"Campus","Lahore",new BigDecimal("200000"),"Administrator",new BigDecimal("25000"),new BigDecimal("50000"),new BigDecimal("5000")));for(int i=1;i<=3;i++)x.add(new ResearchAssistant("R"+i,"Research Assistant "+i,"Campus","Lahore",new BigDecimal("150000"),"Researcher",new BigDecimal("20000"),new BigDecimal("10000")));return List.copyOf(x);} public static void main(String[] args){for(Employee e:sample())System.out.println(e.getCategory()+" | "+e.name()+" | Gross PKR "+e.grossSalary()+" | Net PKR "+e.netSalary());}}
